def transform(grid):
    # For each same-color diagonal seed pair, extend the diagonal ray in both
    # directions to the grid edge, preserving the original background.
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    colors={}
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0,8): colors.setdefault(grid[r][c],[]).append((r,c))
    for color,points in colors.items():
        for r,c in points:
            for rr,cc in points:
                dr,dc=r-rr,c-cc
                if (dr,dc)!=(0,0) and abs(dr)==abs(dc)==1:
                    y,x=r+dr,c+dc
                    while 0<=y<h and 0<=x<w and grid[y][x] in (0,8):
                        out[y][x]=color; y+=dr; x+=dc
    return out

